"OLAYLAR_NAPOLYON_ITALYA_1028:1283-01-01:0":{"b": ["ریجو کالابریا انجو سے آراگون-سسلی کو منتقل (پیدرو سوم کالابریا میں اترا)", "800b47b1"], "d": ["سسلین ویسپرز (1282) کے بعد ریجو انجو کے قبضے میں رہا؛ 1283 کے آغاز میں آراگون کا بادشاہ پیدرو سوم کالابریا میں اترا اور ریجو انجو کے خلاف جنگ کا آراگونی اڈا بنا (جولائی 1284 میں کارلو دانجو نے شہر کا محاصرہ کیا مگر نہ لے سکا)۔ دن ماخذ میں نہیں، سال کی سطح پر۔", "6b2afca7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1302-08-31:0":{"b": ["صلحِ کالتابیلوتا: ریجو کالابریا آراگون-سسلی سے انجو (نیپلز) کو لوٹا", "241c90a7"], "d": ["صلحِ کالتابیلوتا (31 اگست 1302) نے فیدیریکو سوم کے براعظمی کالابریائی املاک سے دستبردار ہونے اور جزیرے کے ٹرینیکریا کی مملکت کے طور پر آراگونی شاخ میں رہنے کی راہ نکالی؛ ریجو انجو کی مملکتِ نیپلز کو منتقل ہوا۔", "c2a155cb"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1318-07-25:0":{"b": ["Jacopo da Carrara I کو Padova کا محافظ اور گورنر منتخب کیا گیا: Padova کمیون ایک سینیور کے پاس چلا گیا", "b3fc0eae"], "d": ["Padova کے اشرافیہ نے Jacopo da Carrara I کو تاحیات محافظ/گورنر منتخب کیا (25 جولائی 1318 کے کچھ ہی بعد)؛ کمیون ایک ہی سینیور کو منتقل ہو گیا۔ دن قطعی نہیں، مدت کا پہلا دن لیا گیا۔", "aa9a4a3f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1351-05-01:0":{"b": ["Zürich دائمی اتحاد کے ذریعے کنفیڈریشن میں شامل ہوا: Luzern، Uri، Schwyz اور Unterwalden کے بعد پانچواں رکن بنا", "78e9419b"], "d": ["Zürich 1 مئی 1351 کو Luzern، Uri، Schwyz اور Unterwalden کے ساتھ دائمی اتحاد کر کے قدیم سوئس کنفیڈریشن کا رکن بنا۔", "4646e7ae"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1399-01-01:0":{"b": ["پیسا جان گیلیاتسو ویسکونتی کو بیچ دیا گیا (گیرارڈو دآپیانو)", "eba05ce2"], "d": ["آپیانو خاندان کی پیسا کی سنیوریا گیرارڈو کے ہاتھوں میلان کے ڈیوک جان گیلیاتسو ویسکونتی کو بیچی گئی؛ پیسا 1399-1402 میں ڈچیِ میلان کے تابع رہا۔ دن ماخذ میں نہیں (سال کی سطح پر 1399)۔", "705f44b2"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1402-09-03:0":{"b": ["جان گیلیاتسو ویسکونتی فوت ہوا: پیسا میلان سے الگ ہو کر گابریئیلے ماریا ویسکونتی کے تحت آزاد رہا", "9e80b0ad"], "d": ["جان گیلیاتسو کی موت (ستمبر 1402) پر پیسا وصیت کے مطابق اس کے ناجائز بیٹے گابریئیلے ماریا ویسکونتی کو منتقل ہوا؛ Treccani EI اور SNS اسے پیسا کی مختصر آزادی کے طور پر بیان کرتے ہیں۔ گابریئیلے ماریا نے 27 اگست 1405 کو اپنے حقوق فلورنس کو بیچ دیے، شہر اکتوبر 1406 میں فتح ہوا۔", "e34aec85"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1506-11-11:0":{"b": ["پوپ Julius II Bologna میں داخل ہوا: Bentivoglio کی سینیوری ختم ہوئی، پاپائیت نے براہِ راست حکمرانی شروع کی", "dc4823a7"], "d": ["پوپ Julius II اپنی فوج کے ساتھ Bologna میں داخل ہوا اور Giovanni II Bentivoglio کو نکال دیا؛ شہر پاپائی ریاست سے جوڑ دیا گیا۔", "9afc6459"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1532-01-01:0":{"b": ["Ancona کی کمیونی آزادی ختم ہوئی: Clemens VII کے ساتھ براہِ راست پاپائی حاکمیت میں آ گیا", "d2fbbb8f"], "d": ["Ancona جمہوریہ کی کمیونی آزادی 1532 میں Clemens VII کے دور میں پاپائیت کی براہِ راست حاکمیت میں آنے سے ختم ہوئی (سال کی حد تک درستی؛ دن/مہینہ نہیں پڑھا گیا)۔", "518c4913"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1536-05-21:0":{"b": ["Genève نے اصلاح کے حق میں ووٹ دیا: بشپ اور Savoy کا تسلط ختم ہوا، Genève جمہوریہ وجود میں آئی", "dcb02e44"], "d": ["21 مئی 1536 کی عام اسمبلی کی رائے شماری سے Genève نے Reformation قبول کی؛ شہر آزاد جمہوریہ کے طور پر Bern کے ساتھ رہا لیکن کنفیڈریشن کا رکن نہیں بنا۔", "fd9e9db5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1540-01-01:0":{"b": ["Baglioni کی سینیوری ختم ہوئی: Perugia Paulus III کی براہِ راست پاپائی حکمرانی میں آ گیا", "3c57f2fe"], "d": ["نمک کی جنگ کے اختتام پر Baglioni کی سینیوری ختم ہوئی، Paulus III نے Rocca Paolina کی تعمیر شروع کی؛ Perugia کمیون کی عملی آزادی ختم ہو گئی (سال کی حد تک درستی؛ دن نہیں پڑھا گیا)۔", "0a01ed80"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1739-10-17:0":{"b": ["کارڈینل Alberoni نے San Marino پر قبضہ کیا: پاپائی حکمرانی مسلط کی گئی", "4d3a4296"], "d": ["Ravenna کے نمائندے کارڈینل Giulio Alberoni نے San Marino پر عسکری قوت سے قبضہ کر کے اسے پاپائیت سے جوڑنے کی کوشش کی؛ لوگوں نے سول نافرمانی سے مزاحمت کی۔", "79343d06"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1740-02-05:0":{"b": ["پوپ Clemens XII نے San Marino کے حقوق تسلیم کیے: آزادی لوٹ آئی", "0783c00e"], "d": ["خفیہ درخواستوں پر پوپ نے San Marino کے حقوق تسلیم کیے؛ Alberoni کا قبضہ ختم ہوا۔", "d3268069"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-05-15:0":{"b": ["Napoleon Milano میں داخل ہوا: آسٹریائی حکمرانی ختم ہوئی", "adce9a6c"], "d": ["Bonaparte اٹلی مہم کی ابتدائی فتوحات کے بعد 15 مئی 1796 کو Milano میں داخل ہوا؛ Lombardia آسٹریا کے ہاتھ سے نکل گیا۔", "2a2ae65e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-06-23:0":{"b": ["Bologna جنگ بندی: Bologna اور Ferrara فرانسیسی ہاتھ میں آ گئے", "5eed42c8"], "d": ["پوپ Pius VI نے Bologna میں جنگ بندی پر دستخط کیے؛ Bologna اور Ferrara کی پاپائی نیابتیں فرانسیسی کنٹرول میں آ گئیں، بھاری تاوان ادا کیا گیا۔", "4447b7b3"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-12-27:0":{"b": ["Cispadane جمہوریہ کا اعلان ہوا (Modena، Reggio، Bologna، Ferrara)", "f9ee3f5a"], "d": ["Reggio کے کانگریس میں Modena، Reggio، Bologna اور Ferrara نے متحد ہو کر Cispadane جمہوریہ کا اعلان کیا؛ Este کی ڈچی عملاً ختم ہو گئی۔", "0529810e"]},
